failed = []
for label, passed in checks:
    print(f"{'PASS' if passed else 'FAIL'}: {label}")
    if not passed:
        failed.append(label)

if failed:
    raise SystemExit(f"Home Feed conversation quality gate failed: {len(failed)} check(s)")
print("HOME FEED VIDEO + THREADS QUALITY GATE: GREEN")
